import java.io.*;
import java.util.*;
public class G{
    public static void main(String[] args) {
        new G().launch();
    }

    void launch() {
        Reader in = new Reader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Problem p = new Problem();
        p.execute(1, in, out);
        out.flush();
        out.close();
    }

    static class Problem {
        static class FlowNetwork {
            Edge[][] graph;
            int vertexCount, src, dest, totalFlow;
            long minCost;
            final long INF = (long)1e15;

            FlowNetwork(int v, int s, int t) {
                vertexCount = v;
                src = s;
                dest = t;
                totalFlow = 0;
                minCost = 0;
                graph = new Edge[v][0];
            }

            void addConnection(int from, int to, int capacity, int cost) {
                Edge forward = new Edge(to, capacity, cost, graph[to].length);
                Edge backward = new Edge(from, 0, -cost, graph[from].length);
                graph[from] = appendEdge(graph[from], forward);
                graph[to] = appendEdge(graph[to], backward);
            }

            Edge[] appendEdge(Edge[] arr, Edge e) {
                Edge[] res = Arrays.copyOf(arr, arr.length + 1);
                res[arr.length] = e;
                return res;
            }

            void prepareArrays() {
                int n = vertexCount;
                Edge[][] temp = new Edge[n][];
                for(int i=0;i<n;i++) {
                    temp[i] = graph[i];
                    graph[i] = new Edge[0];
                }
                graph = temp;
            }

            boolean buildDistances(boolean detectNeg) {
                long[] d = new long[vertexCount];
                Arrays.fill(d, INF);
                d[src] = 0;
                for(int iter=0; iter<vertexCount-1; iter++) {
                    boolean changed = false;
                    for(int u=0; u<vertexCount; u++) {
                        if(d[u] == INF) continue;
                        for(Edge e : graph[u]) {
                            if(e.capacity > 0 && d[u] + e.cost < d[e.to]) {
                                d[e.to] = d[u] + e.cost;
                                changed = true;
                            }
                        }
                    }
                    if(!changed) break;
                }
                if(detectNeg) {
                    for(int u=0; u<vertexCount; u++) {
                        if(d[u] == INF) continue;
                        for(Edge e : graph[u]) {
                            if(e.capacity > 0 && d[u] + e.cost < d[e.to]) return false;
                        }
                    }
                }
                return true;
            }

            class Edge {
                int to, capacity, rev, cost;
                Edge(int t, int c, int w, int r) {to=t; capacity=c; cost=w; rev=r;}
            }

            int[] parentV, parentE, visited, dist;
            int[] queue;

            boolean SPFA() {
                dist = new int[vertexCount];
                parentV = new int[vertexCount];
                parentE = new int[vertexCount];
                visited = new int[vertexCount];
                queue = new int[vertexCount];
                Arrays.fill(dist, Integer.MAX_VALUE/2);
                dist[src] = 0;
                int head = 0, tail = 0;
                queue[tail++] = src;
                while(head != tail) {
                    int u = queue[head++];
                    if(head == vertexCount) head = 0;
                    visited[u] = 2;
                    for(int idx = 0; idx < graph[u].length; idx++) {
                        Edge e = graph[u][idx];
                        if(e.capacity == 0) continue;
                        int nd = dist[u] + e.cost;
                        if(nd < dist[e.to]) {
                            if(visited[e.to] == 0) {
                                queue[tail++] = e.to;
                                if(tail == vertexCount) tail = 0;
                            } else if(visited[e.to] == 2) {
                                if(--head == -1) head += vertexCount;
                                queue[head] = e.to;
                            }
                            visited[e.to] = 1;
                            parentE[e.to] = idx;
                            parentV[e.to] = u;
                            dist[e.to] = nd;
                        }
                    }
                }
                return visited[dest] != 0;
            }

            class Item implements Comparable<Item> {
                int node, priority;
                Item(int n, int p) {node = n; priority = p;}
                public int compareTo(Item o) {return Integer.compare(priority, o.priority);}
            }

            boolean dijkstraAlg() {
                visited = new int[vertexCount];
                dist = new int[vertexCount];
                parentV = new int[vertexCount];
                parentE = new int[vertexCount];
                Arrays.fill(dist, Integer.MAX_VALUE/2);
                PriorityQueue<Item> pq = new PriorityQueue<>();
                pq.add(new Item(src, 0));
                dist[src] = 0;
                o: while(!pq.isEmpty()) {
                    Item cur = pq.poll();
                    while(dist[cur.node] < cur.priority) {
                        if(pq.isEmpty()) break o;
                        cur = pq.poll();
                    }
                    visited[cur.node] = 2;
                    for(int i=0; i<graph[cur.node].length; i++) {
                        Edge e = graph[cur.node][i];
                        if(e.capacity == 0) continue;
                        int reduced = e.cost + dist[cur.node] - dist[e.to];
                        int nd = cur.priority + reduced;
                        if(nd < dist[e.to]) {
                            if(visited[e.to] == 2) return false;
                            pq.add(new Item(e.to, nd));
                            dist[e.to] = nd;
                            parentV[e.to] = cur.node;
                            parentE[e.to] = i;
                            visited[e.to] = 1;
                        }
                    }
                }
                return visited[dest] != 0;
            }

            int augmentPath() {
                int flow = Integer.MAX_VALUE;
                int cur = dest;
                while(cur != src) {
                    int prev = parentV[cur], idx = parentE[cur];
                    flow = Math.min(flow, graph[prev][idx].capacity);
                    cur = prev;
                }
                cur = dest;
                while(cur != src) {
                    int prev = parentV[cur], idx = parentE[cur];
                    graph[prev][idx].capacity -= flow;
                    graph[cur][graph[prev][idx].rev].capacity += flow;
                    cur = prev;
                }
                totalFlow += flow;
                return flow;
            }

            void calculateMinCost() {
                buildDistances(false);
                while(SPFA()) {
                    if(dist[dest] >= Integer.MAX_VALUE/2) break;
                    minCost += dist[dest] * augmentPath();
                }
            }

            void calculateMinCostWithPotential() {
                buildDistances(false);
                while(dijkstraAlg()) {
                    long m = dist[dest] + dist[dest] - dist[src];
                    if(m >= Integer.MAX_VALUE/2) break;
                    minCost += m * augmentPath();
                    for(int i=0; i<vertexCount; i++) {
                        if(visited[i] != 0) dist[i] += dist[i] - dist[src];
                    }
                }
            }
        }

        void execute(int testNum, Reader in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            int k = in.nextInt(), c = in.nextInt(), d = in.nextInt();
            int maxLayers = n + k;
            int terminal = n * maxLayers + 1;
            FlowNetwork net = new FlowNetwork(terminal + 1, 0, terminal);
            int[] occurrences = new int[n + 1], supplies = new int[k + 1];
            for(int i = 1; i <= k; i++) {
                supplies[i] = in.nextInt();
                occurrences[supplies[i]]++;
            }
            for(int i = 1; i <= n; i++) {
                if(occurrences[i] > 0)
                    net.addConnection(0, i, occurrences[i], 0);
            }
            for(int i = 2; i <= n; i++) {
                for(int layer = 0; layer < maxLayers - 1; layer++) {
                    net.addConnection(layer * n + i, (layer + 1) * n + i, k, c);
                }
            }
            for(int i = 1; i <= m; i++) {
                int u = in.nextInt(), v = in.nextInt();
                for(int layer = 0; layer < maxLayers - 1; layer++) {
                    for(int p = 1; p <= k; p++) {
                        if(u != 1)
                            net.addConnection(n * layer + u, n * (layer + 1) + v, 1, d * (2 * p - 1) + c);
                        if(v != 1)
                            net.addConnection(n * layer + v, n * (layer + 1) + u, 1, d * (2 * p - 1) + c);
                    }
                }
            }
            for(int layer = 1; layer < maxLayers; layer++) {
                net.addConnection(layer * n + 1, terminal, k, 0);
            }
            net.prepareArrays();
            net.calculateMinCostWithPotential();
            if(net.totalFlow != k)
                out.println("BUG");
            else
                out.println(net.minCost);
        }
    }

    static class Reader {
        BufferedReader br;
        StringTokenizer st;
        public Reader(InputStream s) { br = new BufferedReader(new InputStreamReader(s)); }
        String next() {
            while(st == null || !st.hasMoreTokens()) {
                String line;
                try{ line = br.readLine(); }catch(Exception e){ return null; }
                if(line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
    }
}
